"""Generates tests/fixtures/numpy-shapes.json: NumPy's own result shape or error for each case."""
import json, numpy as np
pairs = [
 ((3, 4), (4,)), ((3, 4), (3,)), ((3, 4), (3, 1)), ((100, 1), (100,)), ((32, 3, 28, 28), (3, 1, 1)), ((32, 3, 28, 28), (3,)),
 ((2, 3), (3, 2)), ((2, 3), (2, 3)), ((5,), (5,)), ((4,), (4, 3)), ((8, 2, 3), (3, 5)), ((8, 2, 3), (8, 3, 5)), ((8, 2, 3), (7, 3, 5)),
 ((1, 5), (5, 1)), ((), (3, 4)), ((2, 1, 4), (3, 1)), ((64, 784), (784, 10)), ((64, 784), (10, 784)), ((3,), (4,)), ((64, 10), (10,)),
 ((64, 10), (64,)), ((64, 10), (64, 1)), ((2, 3, 4), (4, 2)), ((5, 1, 3), (1, 4, 1)), ((3, 1), (1, 3)), ((10,), (10, 1)),
]
cases = []
for a, b in pairs:
    A = np.zeros(a); B = np.zeros(b)
    for op in ["add", "matmul"]:
        try:
            r = (A + B) if op == "add" else (A @ B)
            cases.append({"a": list(a), "b": list(b), "op": op, "shape": list(np.shape(r))})
        except Exception as e:
            cases.append({"a": list(a), "b": list(b), "op": op, "error": f"{type(e).__name__}: {e}"})
reshape = []
for shape, target in [((32, 3, 28, 28), (32, -1)), ((32, 3, 28, 28), (-1, 28, 28)), ((32, 3, 28, 28), (32, 3, 784)), ((32, 3, 28, 28), (32, 100)),
                      ((6,), (2, 3)), ((12,), (3, 4)), ((12,), (4, 3)), ((2, 3, 4), (-1,)), ((2, 3, 4), (4, -1, 2)), ((64, 784), (64, 28, 28))]:
    A = np.zeros(shape)
    try:
        reshape.append({"a": list(shape), "target": list(target), "shape": list(A.reshape(target).shape)})
    except Exception as e:
        reshape.append({"a": list(shape), "target": list(target), "error": f"{type(e).__name__}: {e}"})
x = np.arange(12)
toy = {"reshape_3x4": x.reshape(3, 4).tolist(), "reshape_4x3": x.reshape(4, 3).tolist(), "transpose_3x4": x.reshape(3, 4).T.tolist()}
y_true = np.array([1.0, 2.0, 3.0, 4.0]); y_pred = np.array([[1.5], [2.0], [2.5], [4.0]])
bug = {"y_true": y_true.tolist(), "y_pred": y_pred.ravel().tolist(), "diff_shape": list((y_pred - y_true).shape),
       "mse_wrong": float(np.mean((y_pred - y_true) ** 2)), "mse_right": float(np.mean((y_pred.ravel() - y_true) ** 2))}
json.dump({"numpy": np.__version__, "note": "Generated by running each operation on np.zeros arrays of these shapes (see tests/fixtures/README.md).",
           "cases": cases, "reshape": reshape, "toy": toy, "silent_bug": bug}, open(__import__("pathlib").Path(__file__).with_name("numpy-shapes.json"), "w"), indent=1)
print(len(cases), "cases"); print(json.dumps(reshape, indent=0)); print(toy); print(bug)
